WITH latest_match AS (SELECT s.*, top1.employee_salary, top1.hire_date FROM departments s LEFT JOIN LATERAL (SELECT c.salary AS employee_salary, c.hire_date FROM employees c WHERE c.dept_id = s.id ORDER BY c.hire_date DESC, c.id DESC LIMIT 1) top1 ON TRUE) SELECT id, dept_name, location, employee_salary, hire_date, CASE WHEN location RLIKE '^(Bangkok|New York)$' THEN 'GROUP_B' WHEN location RLIKE '^(Chiang Mai|Singapore)$' THEN 'CORE' ELSE 'EXTENDED' END AS location_zone FROM latest_match ORDER BY location_zone DESC;
